  const origin = env.BOOKINGS_SITE_ORIGIN || 'https://cuisines-limetta.com'
  const limits = new Map()
  const purge = () => {
    if (!fs.existsSync(folder)) return
    for (const name of fs.readdirSync(folder).filter(name => /^[a-f0-9-]{36}\.json$/i.test(name))) {
      const file = path.join(folder, name)
      if (now() - fs.statSync(file).mtimeMs >= CHOICE_MAX_AGE) fs.unlinkSync(file)
