  const timer = setInterval(() => { try { purge() } catch { console.error('[PRIVACY] PURGE_FAILED') } }, 86400000); timer.unref()
  app.get('/api/privacy/config', (req,res) => res.set('Cache-Control','no-store').json({ metaEnabled: env.META_PIXEL_ENABLED === 'true', pixelId: '1472369584750454' }))
