    const body = Buffer.from(JSON.stringify({ staffId: slot.staffId, start: slot.start, expires: now() + 15 * 60000 })).toString('base64url')
    return `${body}.${sign(body)}`
  }
  function unseal(token) {
    if (typeof token !== 'string' || token.length > 1500) throw new Error('INVALID_SLOT')
    const [body, signature, extra] = token.split('.')
    if (extra || !equal(signature, sign(body))) throw new Error('INVALID_SLOT')
    const slot = JSON.parse(Buffer.from(body, 'base64url').toString())
