  loadingIndicator: createBookingOrb(status, slots, 'recherche des disponibilités', { model: 'globe' }),
  onSelect(slot, { keyboard = false } = {}) {
    chosen = slot
    requestId = slot ? crypto.randomUUID() : undefined
    submit.disabled = !slot
    summary.textContent = slot ? display.format(new Date(slot.start)) : 'Choisissez d’abord votre créneau.'
    result.textContent = ''
    if (slot) {
      trackConversion('slot_selected', {location:'reservation'})
      if (globalThis.matchMedia?.('(max-width: 760px)').matches) {
        document.querySelector('#booking-form-title').focus({ preventScroll: true })
        const reduced = globalThis.matchMedia('(prefers-reduced-motion: reduce)').matches
