form.addEventListener('submit', async event => {
  event.preventDefault()
  if (submitting || !chosen || !form.reportValidity()) return
  const { address, postalCode, city, ...customer } = Object.fromEntries(new FormData(form))
  // Même adresse complète pour Bookings, les mails et l'ajout à l'agenda.
  const fullAddress = address.trim() + ', ' + postalCode.trim() + ' ' + city.trim()
  const payload = { ...customer, projectCity: city.trim(), attribution: getBookingAttribution(), advertisingConsent: getAdvertisingConsent(), address: fullAddress, notes: bookingNotes(), slotId: chosen.id, requestId }
  submitting = true
  lock(true)
  submit.disabled = true
  result.textContent = 'Vérification du créneau et réservation…'
  try {
    bookingOrb.start()
    const response = await fetch('/api/booking/appointments', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    })
    if (response.status === 409) {
      chosen = null
      submitting = false
      lock(false)
      slots.replaceChildren()
      picker.refresh()
      result.textContent = 'Ce créneau n’est plus disponible. Sélectionnez à nouveau une date.'
      return
    }
    const data = await response.json()
    if (response.status === 400 || response.status === 429 || data.error === 'BOOKING_TEST_MODE') {
      submitting = false
      lock(false)
      result.textContent = data.error === 'BOOKING_TEST_MODE' ? 'La réservation sera bientôt disponible. Contactez-moi au 07 67 01 21 02.' : response.status === 429 ? 'Veuillez patienter une minute avant de réessayer.' : 'Vérifiez vos coordonnées et sélectionnez à nouveau votre créneau.'
      return
    }
    if (!response.ok) throw new Error('booking')
    if (!data.confirmed) throw new Error('unconfirmed')
    trackConfirmedBooking(data.advertisingEventId, payload.advertisingConsent)
    trackConversion('booking_confirmed', {location:'reservation'})
    // Le succès ne s'affiche qu'après confirmation explicite du serveur.
    document.querySelector('#booking-success-date').textContent = display.format(new Date(data.start))
    for (const element of document.querySelectorAll('body > header, body > main, body > footer')) element.hidden = true
    document.querySelector('#booking-success').hidden = false
    document.body.classList.add('booking-completed')
    document.title = 'Rendez-vous confirmé | Cuisines Limetta'
    window.scrollTo({ top: 0, behavior: 'instant' })
    document.querySelector('#booking-success-title').focus({ preventScroll: true })

    result.textContent = 'Votre rendez-vous est confirmé. Merci, à bientôt !'
    chosen = null
    summary.textContent = `Rendez-vous confirmé : ${display.format(new Date(data.start))}`
    slots.replaceChildren()
  } catch {
    result.textContent = 'La réservation n’a pas pu être confirmée. Contactez-moi au 07 67 01 21 02 avant de réessayer.'
  } finally {
    bookingOrb.stop()
  }
})

