// Aucun identifiant client ni contenu de formulaire dans les événements.
// Aucun envoi GA : seuls des événements internes de présentation sont émis ici.
import { initSourceConsent } from '../ui/source-consent.js'
const events = new Set(['booking_view', 'booking_click', 'vr_discovery', 'vr_video_play', 'vr_tour_open', 'slot_selected', 'booking_confirmed'])
const locations = new Set(['navigation', 'accueil', 'demonstration', 'visite', 'ambiance', 'parcours', 'reservation', 'autre'])
let initialized = false
export function trackConversion(name, data = {}) {
  if (!events.has(name)) return
  const detail = { name, location: locations.has(data.location) ? data.location : 'autre' }
  // Le suivi ne doit jamais interrompre une réservation.
  try {
    window.dispatchEvent(new CustomEvent('limetta:conversion', { detail }))
    // Internal UI notifications only. Advertising is handled separately after consent.
  } catch { /* Une intégration de mesure indisponible reste sans conséquence. */ }
}
export function initConversionTracking() {
  if (initialized) return
  initialized = true
  initSourceConsent()
  document.addEventListener('click', event => {
    const link = event.target.closest?.('a[href]')
    if (!link) return
    const url = new URL(link.href, location.href)
    if (url.origin === location.origin && url.pathname === '/rdv') trackConversion('booking_click', { location: link.dataset.trackLocation })
    if (link.hasAttribute('data-vr-discovery-link')) trackConversion('vr_discovery', { location: 'accueil' })
  })
  if (document.querySelector('#booking-form')) trackConversion('booking_view', { location: 'reservation' })
}
